/**
 * Simple Local Pickup Checkout Handler
 * Removes shipping address fields when only local pickup is available
 */

// Remove shipping fields when local pickup is the only option
add_filter('woocommerce_checkout_fields', 'remove_shipping_for_local_pickup_only');
function remove_shipping_for_local_pickup_only($fields) {
    // Get available shipping methods for current cart
    $chosen_methods = WC()->session->get('chosen_shipping_methods');
    $available_methods = WC()->shipping()->get_packages();
    
    // Check if only local pickup is available
    $only_local_pickup = true;
    if (!empty($available_methods)) {
        foreach ($available_methods[0]['rates'] as $rate) {
            if ($rate->method_id !== 'local_pickup') {
                $only_local_pickup = false;
                break;
            }
        }
    }
    
    // If only local pickup, remove shipping fields
    if ($only_local_pickup) {
        unset($fields['shipping']);
    }
    
    return $fields;
}

// Force virtual product behavior for local pickup items
add_filter('woocommerce_cart_needs_shipping', 'disable_shipping_for_pickup_only_products');
function disable_shipping_for_pickup_only_products($needs_shipping) {
    // Check if all products in cart are local pickup only
    foreach (WC()->cart->get_cart() as $cart_item) {
        $product = $cart_item['data'];
        $shipping_class = $product->get_shipping_class();
        
        // If any product needs shipping, return true
        if ($shipping_class !== 'local_pickup') {
            return true;
        }
    }
    
    // If we get here, all products are local pickup only
    return false;
}

// Simplify billing fields for local pickup
add_filter('woocommerce_billing_fields', 'simplify_billing_for_local_pickup', 20);
function simplify_billing_for_local_pickup($fields) {
    // Check if shipping is disabled (local pickup only)
    if (!WC()->cart->needs_shipping()) {
        // Make address fields optional
        if (isset($fields['billing_address_1'])) {
            $fields['billing_address_1']['required'] = false;
        }
        if (isset($fields['billing_postcode'])) {
            $fields['billing_postcode']['required'] = false;
        }
        if (isset($fields['billing_state'])) {
            $fields['billing_state']['required'] = false;
        }
        
        // Update city label
        if (isset($fields['billing_city'])) {
            $fields['billing_city']['label'] = 'Your Town';
            $fields['billing_city']['placeholder'] = 'e.g., Lexington, Arlington';
        }
    }
    
    return $fields;
}

